-- Message translation (docs/plan.md §1.69, stream P-7; ARCHITECTURE §5.7, §10.13): one row per
-- translation attempt of one original (a raw record, a thread message or a reach-out's message),
-- beside it and never in place of it; a contact's switch over the client's translation; and the
-- client's own translations counted in usage_platform_daily. 0034 was the next free number on main
-- (§8.3). Additive only: a new table and two columns with defaults, so the previous Worker keeps
-- working (it never reads them). Generated by drizzle-kit from packages/db/src/schema.ts; the
-- grants, row-level security and the immutability trigger at the end are hand-written.
CREATE TABLE "message_translation" (
	"id" uuid PRIMARY KEY DEFAULT uuid_generate_v7() NOT NULL,
	"tenant_id" uuid NOT NULL,
	"raw_record_id" uuid,
	"message_id" uuid,
	"reach_out_id" uuid,
	"field" text DEFAULT 'text' NOT NULL,
	"direction" text NOT NULL,
	"source_language" text NOT NULL,
	"target_language" text NOT NULL,
	"detected_by" text NOT NULL,
	"status" text NOT NULL,
	"reason" text,
	"text" text,
	"original_chars" integer DEFAULT 0 NOT NULL,
	"truncated" boolean DEFAULT false NOT NULL,
	"model" text,
	"tokens_in" integer DEFAULT 0 NOT NULL,
	"tokens_out" integer DEFAULT 0 NOT NULL,
	"cost_usd" numeric(14, 4) DEFAULT '0' NOT NULL,
	"agent_version_id" uuid,
	"run_id" uuid,
	"step_run_id" uuid,
	"requested_by" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "message_translation_id_tenant_key" UNIQUE("id","tenant_id"),
	CONSTRAINT "message_translation_source_check" CHECK (num_nonnulls("message_translation"."raw_record_id", "message_translation"."message_id", "message_translation"."reach_out_id") = 1),
	CONSTRAINT "message_translation_direction_check" CHECK ("message_translation"."direction" in ('in', 'out')),
	CONSTRAINT "message_translation_status_check" CHECK ("message_translation"."status" in ('translated', 'skipped', 'capped', 'refused', 'failed')),
	CONSTRAINT "message_translation_detected_by_check" CHECK ("message_translation"."detected_by" in ('rule', 'model', 'none')),
	CONSTRAINT "message_translation_source_language_check" CHECK ("message_translation"."source_language" in ('en', 'es', 'fr', 'pt-BR', 'it', 'de', 'unknown')),
	CONSTRAINT "message_translation_target_language_check" CHECK ("message_translation"."target_language" in ('en', 'es', 'fr', 'pt-BR', 'it', 'de')),
	CONSTRAINT "message_translation_text_check" CHECK (("message_translation"."status" = 'translated') = ("message_translation"."text" is not null)),
	CONSTRAINT "message_translation_field_check" CHECK (length("message_translation"."field") between 1 and 200),
	CONSTRAINT "message_translation_amounts_check" CHECK ("message_translation"."tokens_in" >= 0 and "message_translation"."tokens_out" >= 0 and "message_translation"."cost_usd" >= 0 and "message_translation"."original_chars" >= 0),
	CONSTRAINT "message_translation_step_check" CHECK ("message_translation"."step_run_id" is null or ("message_translation"."run_id" is not null and "message_translation"."agent_version_id" is not null))
);
